// Validate raw telemetry against telemetry-inbound-schema.json
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json || {};
  const account = body.account || {};
  const metrics = account.metrics;
  const errors = [];

  if (!body.event_id) errors.push('Missing required field: event_id');
  if (!body.timestamp) errors.push('Missing required field: timestamp');
  if (!account.account_id) errors.push('Missing required field: account.account_id');
  if (!account.account_name) errors.push('Missing required field: account.account_name');
  if (account.arr_usd === undefined || account.arr_usd === null || isNaN(Number(account.arr_usd)))
    errors.push('Missing or invalid field: account.arr_usd');
  if (!account.contract_end_date) errors.push('Missing required field: account.contract_end_date');
  if (!metrics || typeof metrics !== 'object') errors.push('Missing required field: account.metrics');

  out.push({
    json: {
      valid: errors.length === 0,
      validation_stage: 'inbound-schema',
      validation_errors: errors,
      event_id: body.event_id || null,
      timestamp: body.timestamp || null,
      account: account,
      raw_payload: body,
    },
  });
}
return out;

// Enrich telemetry: renewal window + seat utilization
const out = [];
for (const item of $input.all()) {
  const account = item.json.account || {};
  const metrics = account.metrics || {};

  // days_until_renewal
  let days_until_renewal = null;
  if (account.contract_end_date) {
    const end = new Date(account.contract_end_date);
    if (!isNaN(end.getTime())) {
      const now = new Date();
      days_until_renewal = Math.round((end.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
    }
  }

  // seat_utilization_pct
  const activeUsers = Number(metrics.active_users_30d) || 0;
  const licensedSeats = Number(metrics.licensed_seats) || 0;
  const seat_utilization_pct = licensedSeats > 0
    ? Math.round((activeUsers / licensedSeats) * 10000) / 100
    : 0;

  const health_inputs = {
    account_id: account.account_id,
    account_name: account.account_name,
    arr_usd: Number(account.arr_usd) || 0,
    csm_email: account.csm_email || null,
    contract_end_date: account.contract_end_date,
    days_until_renewal,
    seat_utilization_pct,
    active_users_30d: activeUsers,
    licensed_seats: licensedSeats,
    adoption_pct: Number(metrics.adoption_pct) || 0,
    logins_per_week: Number(metrics.logins_per_week) || 0,
    p1_incidents: Number(metrics.p1_incidents) || 0,
    nps: metrics.nps === undefined || metrics.nps === null ? null : Number(metrics.nps),
  };

  out.push({
    json: {
      event_id: item.json.event_id,
      timestamp: item.json.timestamp,
      account,
      health_inputs,
      raw_payload: item.json.raw_payload,
    },
  });
}
return out;

// Validate merged data against account-enriched-schema.json
const out = [];
for (const item of $input.all()) {
  const h = item.json.health_inputs || {};
  const errors = [];

  if (!h.account_id) errors.push('Enriched: missing account_id');
  if (!h.account_name) errors.push('Enriched: missing account_name');
  if (h.days_until_renewal === null || h.days_until_renewal === undefined)
    errors.push('Enriched: days_until_renewal could not be computed (invalid contract_end_date)');
  if (h.licensed_seats <= 0) errors.push('Enriched: licensed_seats must be > 0');
  if (h.seat_utilization_pct === null || isNaN(h.seat_utilization_pct))
    errors.push('Enriched: seat_utilization_pct could not be computed');

  out.push({
    json: {
      ...item.json,
      valid: errors.length === 0,
      validation_stage: 'account-enriched',
      validation_errors: errors,
      raw_payload: item.json.raw_payload,
    },
  });
}
return out;

// Deterministic health scoring (max 100)
const out = [];
for (const item of $input.all()) {
  const h = item.json.health_inputs || {};

  // Seat Utilization (max 30)
  const su = Number(h.seat_utilization_pct) || 0;
  let seatScore = 0;
  if (su >= 85) seatScore = 30;
  else if (su >= 60) seatScore = 20;
  else if (su >= 30) seatScore = 10;
  else seatScore = 0;

  // Adoption (max 15)
  const adoption = Number(h.adoption_pct) || 0;
  const adoptionScore = adoption >= 70 ? 15 : 0;

  // Logins (max 10)
  const logins = Number(h.logins_per_week) || 0;
  const loginsScore = logins >= 5 ? 10 : 0;

  // Support Health (max 25)
  const p1 = Number(h.p1_incidents) || 0;
  let supportScore = 0;
  if (p1 === 0) supportScore = 25;
  else if (p1 === 1) supportScore = 10;
  else supportScore = 0;

  // NPS (max 20)
  const nps = h.nps === null || h.nps === undefined ? -1 : Number(h.nps);
  let npsScore = 0;
  if (nps >= 9) npsScore = 20;
  else if (nps >= 7) npsScore = 12;
  else npsScore = 0;

  const health_score = seatScore + adoptionScore + loginsScore + supportScore + npsScore;

  // Tier
  let tier;
  if (health_score < 45) tier = 'High Churn Risk';
  else if (health_score < 75) tier = 'Stable / Monitor';
  else tier = 'Healthy / Expansion Candidate';

  // Expansion triggers
  const expansion_triggered =
    su >= 85 || adoption >= 80 || (h.arr_usd >= 100000 && su >= 75);

  // Routing action
  let routing_action;
  if (health_score < 45) routing_action = 'churn_risk';
  else if (health_score >= 75 && expansion_triggered) routing_action = 'expansion';
  else routing_action = 'monitor';

  // Risk factors (human-readable)
  const risk_factors = [];
  if (su < 60) risk_factors.push('Low seat utilization (' + su + '%)');
  if (adoption < 70) risk_factors.push('Low adoption (' + adoption + '%)');
  if (logins < 5) risk_factors.push('Low login frequency (' + logins + '/wk)');
  if (p1 >= 2) risk_factors.push(p1 + ' open P1 incidents');
  if (nps >= 0 && nps < 7) risk_factors.push('Detractor NPS (' + nps + ')');
  if (h.days_until_renewal !== null && h.days_until_renewal <= 90)
    risk_factors.push('Renewal in ' + h.days_until_renewal + ' days');

  // Expansion rationale
  const expansion_rationale = [];
  if (su >= 85) expansion_rationale.push('High seat utilization (' + su + '%) — seats near capacity');
  if (adoption >= 80) expansion_rationale.push('Strong adoption (' + adoption + '%)');
  if (nps >= 9) expansion_rationale.push('Promoter NPS (' + nps + ')');
  if (h.arr_usd >= 100000) expansion_rationale.push('Strategic ARR ($' + h.arr_usd + ')');

  const scoring_breakdown = {
    seat_utilization: seatScore,
    adoption: adoptionScore,
    logins: loginsScore,
    support_health: supportScore,
    nps: npsScore,
    max_score: 100,
  };

  out.push({
    json: {
      event_id: item.json.event_id,
      account_id: h.account_id,
      account_name: h.account_name,
      arr_usd: h.arr_usd,
      csm_email: h.csm_email,
      contract_end_date: h.contract_end_date,
      days_until_renewal: h.days_until_renewal,
      health_score,
      tier,
      routing_action,
      expansion_triggered,
      scoring_breakdown,
      risk_factors,
      expansion_rationale,
      health_inputs: h,
    },
  });
}
return out;

